// ═══════════════════════════════════════════════════════════
// BUILD CONFIG — Calcul de la période + règle week-end
// ═══════════════════════════════════════════════════════════

// Détecter si exécution manuelle
const isManual = $execution?.mode === 'manual';

// Date courante en timezone Europe/Paris
const now = new Date();
const formatter = new Intl.DateTimeFormat('fr-FR', {
  timeZone: 'Europe/Paris',
  year: 'numeric', month: '2-digit', day: '2-digit'
});
const parts = formatter.formatToParts(now);
const day   = parseInt(parts.find(p => p.type === 'day').value);
const month = parseInt(parts.find(p => p.type === 'month').value);
const year  = parseInt(parts.find(p => p.type === 'year').value);

// Jour de semaine du 20 de ce mois (0=Dim, 6=Sam)
const twentieth = new Date(Date.UTC(year, month - 1, 20));
const dow20 = twentieth.getUTCDay();
const DOW_NAMES = ['Dim','Lun','Mar','Mer','Jeu','Ven','Sam'];

// ── Règle week-end ─────────────────────────────────────
// - Jour 20 normal          → toujours run
// - Jour 21, 20=Dim (0)     → run (Lundi de rattrapage)
// - Jour 22, 20=Sam (6)     → run (Lundi de rattrapage)
let shouldRun = false;
let runReason = '';

if (isManual) {
  shouldRun = true;
  runReason = 'Exécution manuelle — règle de date ignorée';
} else if (day === 20) {
  shouldRun = true;
  runReason = `Exécution planifiée — 20 ${DOW_NAMES[dow20]} (jour ouvré)`;
} else if (day === 21 && dow20 === 0) {
  shouldRun = true;
  runReason = 'Règle week-end : 20 était Dimanche → rattrapage Lundi 21';
} else if (day === 22 && dow20 === 6) {
  shouldRun = true;
  runReason = 'Règle week-end : 20 était Samedi → rattrapage Lundi 22';
} else {
  runReason = `Pas de run : jour ${day}, 20 était ${DOW_NAMES[dow20]} — aucune règle ne correspond`;
}

// ── Période d'audit = mois précédent ─────────────────
const auditMonth = month === 1 ? 12 : month - 1;
const auditYear  = month === 1 ? year - 1 : year;
const auditMonthPad = String(auditMonth).padStart(2, '0');
const reportKey     = `audit-${auditYear}-${auditMonthPad}`;
const pdfFileName   = `${reportKey}.pdf`;

// Jours dans le mois d'audit
const lastDay = new Date(auditYear, auditMonth, 0).getDate();
const periodStart = `${auditYear}-${auditMonthPad}-01`;
const periodEnd   = `${auditYear}-${auditMonthPad}-${String(lastDay).padStart(2, '0')}`;

const MONTH_NAMES_FR = ['','Janvier','Février','Mars','Avril','Mai','Juin',
  'Juillet','Août','Septembre','Octobre','Novembre','Décembre'];
const periodLabel = `${MONTH_NAMES_FR[auditMonth]} ${auditYear}`;

return [{ json: {
  shouldRun,
  runReason,
  isManual,
  today: { day, month, year, dow20, dowName20: DOW_NAMES[dow20] },
  reportKey,
  pdfFileName,
  periodStart,
  periodEnd,
  periodLabel,
  auditMonth,
  auditYear,
  executedAt: now.toISOString()
}}];

// ═══════════════════════════════════════════════════════
// IDEMPOTENCE — Vérifie si le rapport a déjà été généré
// Utilise $getWorkflowStaticData() pour persister l'état
// ═══════════════════════════════════════════════════════

const input = $input.first().json;
const { reportKey, isManual } = input;

// Lire l'état persistant du workflow
const staticData = $getWorkflowStaticData('global');
if (!staticData.completedReports) staticData.completedReports = {};

// FORCE_RERUN : env var ou exécution manuelle
const forceRerun = $env.FORCE_RERUN === 'true' || isManual;

const previousRun  = staticData.completedReports[reportKey] || null;
const alreadyDone  = !!previousRun && !forceRerun;

if (alreadyDone) {
  console.log(`[idempotence] ${reportKey} déjà généré le ${previousRun.completedAt} — skip (FORCE_RERUN=false)`);
} else if (previousRun && forceRerun) {
  console.log(`[idempotence] ${reportKey} existait mais FORCE_RERUN=true — relance`);
} else {
  console.log(`[idempotence] ${reportKey} — premier run`);
}

return [{ json: {
  ...input,
  alreadyDone,
  forceRerun,
  previousRun
}}];

// ═══════════════════════════════════════════════════════
// MOCK DATA — Données simulées pour dry run / tests
// DATAFORSEO_DRY_RUN=true → ce node est actif
// ═══════════════════════════════════════════════════════

const input  = $input.first().json;
const domain = $env.TARGET_DOMAIN || 'schoolswp.com';

console.log(`[mock] DRY-RUN — données mock pour ${domain}`);

return [{ json: {
  ...input,
  _source: 'mock',
  domain,
  organic: {
    keywords_total:    176,
    keywords_top3:     15,
    keywords_top10:    79,
    etv:               1790,
    etv_previous:      1728,
    etv_change_pct:    3.6,
    traffic_value_eur: 5350
  },
  positions: {
    pos_1: 2, pos_2_3: 13, pos_4_10: 64,
    pos_11_20: 34, pos_21_30: 12, pos_31_100: 51
  },
  momentum: {
    keywords_new: 49, keywords_up: 67,
    keywords_down: 45, keywords_lost: 76
  },
  top_keywords: [
    { keyword: 'o2switch',                volume: 33100, position: 38, etv: 69,  type: 'affiliation' },
    { keyword: '5euros.com',              volume: 8100,  position: 6,  etv: 274, type: 'affiliation' },
    { keyword: '5 euros',                 volume: 4400,  position: 7,  etv: 113, type: 'affiliation' },
    { keyword: 'linksgarden',             volume: 1300,  position: 4,  etv: 86,  type: 'affiliation' },
    { keyword: 'thot seo',                volume: 1300,  position: 8,  etv: 26,  type: 'affiliation' },
    { keyword: 'local wp',                volume: 1600,  position: 13, etv: 9,   type: 'tool' },
    { keyword: 'maintenance wordpress',   volume: 1600,  position: 79, etv: 3,   type: 'core' },
    { keyword: 'plugin wordpress',        volume: 1000,  position: 80, etv: 2,   type: 'core' },
    { keyword: 'r\u00e9f\u00e9rencement wordpress', volume: 1000, position: 76, etv: 2, type: 'core' }
  ],
  competitors: [
    { domain: 'wpmarmite.com',  intersections: 105, etv: 57647 },
    { domain: 'webandseo.fr',   intersections: 77,  etv: 21983 },
    { domain: 'wpbeginner.com', intersections: 70,  etv: 8593  },
    { domain: 'weadown.com',    intersections: 47,  etv: 411   }
  ],
  lighthouse: { performance: 100, best_practices: 100, seo: 92, accessibility: 91 }
}}];

// ═══════════════════════════════════════════════════════
// BUILD COLLECTED DATA — Agrège les 4 réponses DataForSEO
// ═══════════════════════════════════════════════════════

const config = $('Check Idempotence').first().json;
const domain = $env.TARGET_DOMAIN || 'schoolswp.com';

// Helper d'accès sécurisé aux nodes précédents
const safe = (fn) => { try { return fn(); } catch(e) { return null; } };

// ── Domain Rank Overview ───────────────────────────────
const rankRaw  = safe(() => $('DFS: Domain Rank').first().json);
const rankData = rankRaw?.tasks?.[0]?.result?.[0] || {};
const org      = rankData?.metrics?.organic || {};

const pos_1      = org.pos_1 || 0;
const pos_2_3    = org.pos_2_3 || 0;
const pos_4_10   = org.pos_4_10 || ((org.pos_4_6 || 0) + (org.pos_7_10 || 0));
const pos_11_20  = org.pos_11_20 || 0;
const pos_21_30  = org.pos_21_30 || 0;
const pos_31_100 = (org.pos_31_40 || 0) + (org.pos_41_50 || 0)
                 + (org.pos_51_60 || 0) + (org.pos_61_70 || 0)
                 + (org.pos_71_80 || 0) + (org.pos_81_90 || 0)
                 + (org.pos_91_100 || 0);

// ── Ranked Keywords ────────────────────────────────────
const kwRaw   = safe(() => $('DFS: Ranked Keywords').first().json);
const kwItems = kwRaw?.tasks?.[0]?.result?.[0]?.items || [];

const top_keywords = kwItems.slice(0, 20).map(item => {
  const kd = item.keyword_data || {};
  const si = item.ranked_serp_element?.serp_item || {};
  return {
    keyword:  kd.keyword || '',
    volume:   kd.keyword_info?.search_volume || 0,
    position: si.rank_absolute || si.rank_group || 99,
    etv:      si.etv || 0,
    type:     'organic'
  };
});

// ── Competitors ────────────────────────────────────────
const compRaw   = safe(() => $('DFS: Competitors').first().json);
const compItems = compRaw?.tasks?.[0]?.result?.[0]?.items || [];

const competitors = compItems.slice(0, 5).map(item => {
  const m = item.competitor_metrics?.organic
           || item.metrics?.organic
           || {};
  return {
    domain:        item.domain || '',
    intersections: item.intersections || 0,
    etv:           m.etv || 0
  };
});

// ── Lighthouse ─────────────────────────────────────────
const lhRaw    = safe(() => $('DFS: Lighthouse').first().json);
const lhResult = lhRaw?.tasks?.[0]?.result?.[0] || {};
const cats     = lhResult.categories || {};

const lighthouse = {
  performance:    Math.round((cats.performance?.score                          || 0) * 100),
  best_practices: Math.round(((cats['best-practices'] || cats.best_practices)?.score || 0) * 100),
  seo:            Math.round((cats.seo?.score                                  || 0) * 100),
  accessibility:  Math.round((cats.accessibility?.score                        || 0) * 100)
};

// ── Momentum (new/up/down/lost) ────────────────────────
const momentum = {
  keywords_new:  org.new_keywords   || 0,
  keywords_up:   org.up_keywords    || 0,
  keywords_down: org.down_keywords  || 0,
  keywords_lost: org.lost_keywords  || 0
};

// ── Organic summary ────────────────────────────────────
const keywords_total = org.count || org.keywords_count || kwItems.length;
const keywords_top3  = pos_1 + pos_2_3;
const keywords_top10 = keywords_top3 + pos_4_10;
const etv            = org.etv || 0;
const traffic_value  = org.estimated_paid_traffic_cost || 0;

console.log(`[collect] DataForSEO live data: ${keywords_total} kw, ETV ${etv}, ${top_keywords.length} top kw, ${competitors.length} competitors, LH perf=${lighthouse.performance}`);

return [{ json: {
  // Champs de routing issus du config
  reportKey:   config.reportKey,
  pdfFileName: config.pdfFileName,
  periodStart: config.periodStart,
  periodEnd:   config.periodEnd,
  periodLabel: config.periodLabel,
  executedAt:  config.executedAt,
  _source: 'dataforseo',
  domain,
  organic: {
    keywords_total,
    keywords_top3,
    keywords_top10,
    etv,
    etv_previous:      etv,
    etv_change_pct:    0,
    traffic_value_eur: traffic_value
  },
  positions: { pos_1, pos_2_3, pos_4_10, pos_11_20, pos_21_30, pos_31_100 },
  momentum,
  top_keywords,
  competitors,
  lighthouse
}}];

// ═══════════════════════════════════════════════════════
// NORMALIZE — Conforme à /report/schema.json
// ═══════════════════════════════════════════════════════

const d = $input.first().json;

const normalized = {
  meta: {
    domain:      d.domain,
    reportKey:   d.reportKey,
    generatedAt: new Date().toISOString(),
    period: {
      start: d.periodStart,
      end:   d.periodEnd,
      label: d.periodLabel
    },
    source: d._source || 'dataforseo'
  },
  organic:      d.organic,
  positions:    d.positions,
  momentum:     d.momentum,
  top_keywords: d.top_keywords,
  competitors:  d.competitors,
  lighthouse:   d.lighthouse,
  // Champs de routing conservés
  reportKey:    d.reportKey,
  pdfFileName:  d.pdfFileName,
  periodLabel:  d.periodLabel,
  executedAt:   d.executedAt
};

return [{ json: normalized }];

