// ═══════════════════════════════════════════════════════
// MERGE — Combine les données normalisées et l'analyse IA
// ═══════════════════════════════════════════════════════

const dataNode = $('Normalize Data').first().json;
const aiRaw    = $input.first().json;

// Parser la réponse OpenAI
let aiAnalysis = {};
try {
  const aiText = aiRaw.choices?.[0]?.message?.content || '{}';
  aiAnalysis = JSON.parse(aiText);
} catch(e) {
  console.warn('[merge] Impossible de parser la réponse IA:', e.message);
  aiAnalysis = {
    summary: 'Analyse IA non disponible.',
    top_insights: [],
    risks: [],
    priority_actions: []
  };
}

return [{ json: { ...dataNode, ai_analysis: aiAnalysis } }];

// ═══════════════════════════════════════════════════════
// RENDER HTML — Injecte les données dans template.html
// ═══════════════════════════════════════════════════════

const fs   = require('fs');
const d    = $input.first().json;
const ai   = d.ai_analysis || {};
const o    = d.organic;
const pos  = d.positions;
const mom  = d.momentum;
const lh   = d.lighthouse;

// Lire le template
let html = fs.readFileSync('/report/template.html', 'utf8');

// ── Helpers ──────────────────────────────────────────
const scoreClass = (v) => v >= 90 ? 'perfect' : v >= 70 ? 'good' : 'warn';
const posClass   = (p) => p <= 10 ? 'pos-good' : p <= 30 ? 'pos-mid' : 'pos-bad';
const fmt        = (n) => n?.toLocaleString('fr-FR') || '—';
const sign       = (n) => n >= 0 ? `+${n.toFixed(1)}%` : `${n.toFixed(1)}%`;

const typeTag = (t) => ({
  'affiliation': '<span class="tag orange">Affiliation</span>',
  'core':        '<span class="tag">Core WP</span>',
  'tool':        '<span class="tag blue">Outil WP</span>',
  'brand':       '<span class="tag blue">Brand</span>'
})[t] || '<span class="tag">Autre</span>';

// ── Positions rows ────────────────────────────────────
const total  = o.keywords_total || 1;
const posRows = [
  ['Top 3',    pos.pos_1 + pos.pos_2_3,       'Trafic solide garanti',              'pos-good'],
  ['Top 10',   pos.pos_1 + pos.pos_2_3 + pos.pos_4_10, 'Potentiel maximal',         'pos-good'],
  ['11–20',    pos.pos_11_20,                 'À optimiser — seuil top 10 proche',  'pos-mid'],
  ['21–50',    (pos.pos_21_30 || 0),          'Enrichissement contenu nécessaire',  'pos-mid'],
  ['51–100',   (pos.pos_31_100 || 0),         'Long tail — faible visibilité',      'pos-bad']
].map(([zone, count, label, cls]) =>
  `<tr><td><strong>${zone}</strong></td><td class="${cls}"><strong>${count}</strong></td><td>${Math.round(count/total*100)} %</td><td>${label}</td></tr>`
).join('\n');

// ── Top keywords rows ────────────────────────────────
const kwRows = (d.top_keywords || []).map(kw =>
  `<tr><td>${kw.keyword}</td><td>${fmt(kw.volume)}</td><td class="${posClass(kw.position)}"><strong>${kw.position}</strong></td><td>${kw.etv.toFixed(0)}</td><td>${typeTag(kw.type)}</td></tr>`
).join('\n');

// ── Competitors rows ─────────────────────────────────
const compRows = (d.competitors || []).map((c, i) => {
  const isMain = i === 0 ? '<span class="tag">Concurrent FR #1</span>' : '';
  return `<tr><td>${isMain ? '<strong>' + c.domain + '</strong>' : c.domain}</td><td><strong>${c.intersections}</strong></td><td>${fmt(c.etv)}</td><td>${isMain}</td></tr>`;
}).join('\n');

// ── AI Insights ──────────────────────────────────────
const insightItems = (ai.top_insights || []).map(i => `<li>${i}</li>`).join('\n');
const riskItems    = (ai.risks || []).map(r => `<li>${r}</li>`).join('\n');

const priorityCards = (ai.priority_actions || []).map(a =>
  `<div class="priority-card"><div class="p-num">0${a.num}</div><h4>${a.title}</h4><p>${a.description}</p></div>`
).join('\n');

// ── Commentaires auto ────────────────────────────────
const lhComment = lh.performance === 100
  ? '<strong>Socle technique exceptionnel.</strong> Performance 100/100 — moins de 1 % des sites WordPress l\'atteignent.'
  : `<strong>Performance Lighthouse : ${lh.performance}/100.</strong> Des optimisations sont possibles.`;

const etvChange = sign(o.etv_change_pct);
const kwStrategicComment = `<strong>Diagnostic :</strong> ${ai.summary || 'Analyse IA non disponible.'}`;

// ── Substitutions ────────────────────────────────────
const replacements = {
  '{{DOMAIN}}':           d.meta.domain,
  '{{PERIOD_LABEL}}':     d.meta.period.label,
  '{{GENERATED_AT}}':     new Date(d.meta.generatedAt).toLocaleDateString('fr-FR', { year:'numeric', month:'long', day:'numeric' }),
  '{{LH_PERFORMANCE}}':   String(lh.performance),
  '{{LH_BEST_PRACTICES}}':String(lh.best_practices),
  '{{LH_SEO}}':           String(lh.seo),
  '{{LH_ACCESSIBILITY}}': String(lh.accessibility),
  '{{LH_PERF_CLASS}}':    scoreClass(lh.performance),
  '{{LH_BP_CLASS}}':      scoreClass(lh.best_practices),
  '{{LH_SEO_CLASS}}':     scoreClass(lh.seo),
  '{{LH_A11Y_CLASS}}':    scoreClass(lh.accessibility),
  '{{LH_COMMENT}}':       lhComment,
  '{{KW_TOTAL}}':         String(o.keywords_total),
  '{{ETV}}':              fmt(o.etv),
  '{{ETV_CHANGE}}':       etvChange,
  '{{TRAFFIC_VALUE}}':    fmt(o.traffic_value_eur) + ' €',
  '{{KW_NEW}}':           String(mom.keywords_new),
  '{{KW_UP}}':            String(mom.keywords_up),
  '{{KW_DOWN}}':          String(mom.keywords_down),
  '{{KW_LOST}}':          String(mom.keywords_lost),
  '{{POSITIONS_ROWS}}':   posRows,
  '{{TOP_KEYWORDS_ROWS}}':kwRows,
  '{{COMPETITORS_ROWS}}': compRows,
  '{{AI_SUMMARY}}':       ai.summary || '—',
  '{{AI_INSIGHTS}}':      insightItems || '<li>Aucun insight généré.</li>',
  '{{AI_RISKS}}':         riskItems    || '<li>Aucun risque identifié.</li>',
  '{{PRIORITY_ACTIONS}}': priorityCards || '<p>Aucune action générée.</p>',
  '{{KW_STRATEGIC_COMMENT}}': kwStrategicComment
};

for (const [token, value] of Object.entries(replacements)) {
  html = html.split(token).join(value);
}

return [{ json: { ...d, html } }];

// ═══════════════════════════════════════════════════════
// SAVE PDF — Écrit le PDF sur le volume /artifacts
// ═══════════════════════════════════════════════════════

const fs   = require('fs');
const path = require('path');

const metaNode    = $('Normalize Data').first().json;
const binaryData  = $input.first().binary?.data;

if (!binaryData) {
  throw new Error('PDF binary data manquant — le PDF Service a-t-il bien répondu ?');
}

const artifactsPath = $env.ARTIFACTS_PATH || '/artifacts';
if (!fs.existsSync(artifactsPath)) {
  fs.mkdirSync(artifactsPath, { recursive: true });
}

const pdfPath = path.join(artifactsPath, metaNode.pdfFileName);
const pdfBuffer = Buffer.from(binaryData.data, binaryData.mimeType === 'application/pdf' ? undefined : 'base64');

fs.writeFileSync(pdfPath, pdfBuffer);

const stats = fs.statSync(pdfPath);
console.log(`[save] PDF sauvegardé : ${pdfPath} (${Math.round(stats.size / 1024)} Ko)`);

return [{ json: {
  ...metaNode,
  pdfPath,
  pdfSizeKb: Math.round(stats.size / 1024),
  savedAt:   new Date().toISOString()
}, binary: $input.first().binary }];

