// ═══════════════════════════════════════════════════════
// MARK COMPLETE — Persiste l'état d'achèvement
// ═══════════════════════════════════════════════════════

const d = $('Save PDF to Disk').first().json;
const staticData = $getWorkflowStaticData('global');

if (!staticData.completedReports) staticData.completedReports = {};

staticData.completedReports[d.reportKey] = {
  completedAt:  new Date().toISOString(),
  pdfPath:      d.pdfPath,
  pdfSizeKb:    d.pdfSizeKb,
  reportKey:    d.reportKey,
  periodLabel:  d.periodLabel
};

// Log de fin
const duration = Math.round((new Date() - new Date(d.executedAt)) / 1000);
console.log(`
╔══════════════════════════════════════════════╗
║  ✅ AUDIT TERMINÉ — ${d.reportKey}        
║  Durée     : ${duration}s
║  PDF       : ${d.pdfFileName} (${d.pdfSizeKb} Ko)
║  Statut    : marqué complet dans staticData
╚══════════════════════════════════════════════╝`);

return [{ json: {
  ...d,
  auditComplete: true,
  durationSeconds: duration
}}];
